from AlgorithmImports import *


class IndependentStrategiesAlgorithm(QCAlgorithm):
    SMA_PERIOD = 20
    RSI_PERIOD = 14

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            security = self.AddEquity(
                ticker,
                Resolution.Daily,
                Market.USA,
                False
            )
            self.symbols[ticker] = security.Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]
        self.required_symbols = tuple(self.symbols.values())

        self.spy_sma = SimpleMovingAverage(self.SMA_PERIOD)
        self.aapl_rsi = RelativeStrengthIndex(
            self.RSI_PERIOD,
            MovingAverageType.Wilders
        )

        self.previous_spy_close = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.spy_lot_shares = 0
        self.aapl_lot_shares = 0

    def OnData(self, data):
        self._apply_splits(data)

        spy_crossed_above = False
        spy_crossed_below = False

        if self.spy in data.Bars:
            spy_bar = data.Bars[self.spy]
            previous_sma_ready = self.spy_sma.IsReady
            previous_sma = (
                self.spy_sma.Current.Value
                if previous_sma_ready
                else None
            )

            self.spy_sma.Update(spy_bar.EndTime, spy_bar.Close)

            if previous_sma_ready and self.previous_spy_close is not None:
                current_sma = self.spy_sma.Current.Value
                spy_crossed_above = (
                    self.previous_spy_close <= previous_sma
                    and spy_bar.Close > current_sma
                )
                spy_crossed_below = (
                    self.previous_spy_close >= previous_sma
                    and spy_bar.Close < current_sma
                )

            self.previous_spy_close = spy_bar.Close

        if self.aapl in data.Bars:
            aapl_bar = data.Bars[self.aapl]

            if self.previous_aapl_close is None:
                self.aapl_red_streak = 0
            elif aapl_bar.Close < self.previous_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

            self.previous_aapl_close = aapl_bar.Close
            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_bar.Close)

        if any(symbol not in data.Bars for symbol in self.required_symbols):
            return

        if not self.spy_sma.IsReady or not self.aapl_rsi.IsReady:
            return

        spy_close = data.Bars[self.spy].Close
        aapl_close = data.Bars[self.aapl].Close

        # Evaluate all sells before any buys.
        if self.spy_lot_shares > 0 and spy_crossed_below:
            self.MarketOrder(
                self.spy,
                -self.spy_lot_shares,
                tag="Strategy A: close crossed below SMA"
            )
            self.spy_lot_shares = 0

        if (
            self.aapl_lot_shares > 0
            and self.aapl_rsi.Current.Value > 60
        ):
            self.MarketOrder(
                self.aapl,
                -self.aapl_lot_shares,
                tag="Strategy B: RSI above 60"
            )
            self.aapl_lot_shares = 0

        if self.spy_lot_shares == 0 and spy_crossed_above:
            target_value = 0.40 * float(self.Portfolio.TotalPortfolioValue)
            quantity = int(target_value // float(spy_close))

            if quantity > 0:
                self.MarketOrder(
                    self.spy,
                    quantity,
                    tag="Strategy A: close crossed above SMA"
                )
                self.spy_lot_shares = quantity

        if self.aapl_lot_shares == 0 and self.aapl_red_streak >= 3:
            if float(self.Portfolio.Cash) >= 20_000:
                quantity = int(20_000 // float(aapl_close))

                if quantity > 0:
                    self.MarketOrder(
                        self.aapl,
                        quantity,
                        tag="Strategy B: three consecutive red days"
                    )
                    self.aapl_lot_shares = quantity

    def _apply_splits(self, data):
        if self.spy in data.Splits and self.spy_lot_shares > 0:
            split = data.Splits[self.spy]
            if (
                split.Type == SplitType.SplitOccurred
                and split.SplitFactor > 0
            ):
                self.spy_lot_shares = int(
                    round(
                        self.spy_lot_shares
                        / float(split.SplitFactor)
                    )
                )

        if self.aapl in data.Splits and self.aapl_lot_shares > 0:
            split = data.Splits[self.aapl]
            if (
                split.Type == SplitType.SplitOccurred
                and split.SplitFactor > 0
            ):
                self.aapl_lot_shares = int(
                    round(
                        self.aapl_lot_shares
                        / float(split.SplitFactor)
                    )
                )

