from AlgorithmImports import *
from decimal import Decimal


class IndependentParallelStrategiesAlgorithm(QCAlgorithm):

    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.symbols = {
            ticker: self.add_equity(ticker, Resolution.DAILY).symbol
            for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        }
        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        # The strategy specification does not state an SMA period.
        self.sma_period = 20
        self.spy_sma = SimpleMovingAverage(self.sma_period)
        self.aapl_rsi = RelativeStrengthIndex(
            14, MovingAverageType.WILDERS
        )

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0
        self.aapl_samples = 0

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0
        self.strategy_a_pending = False
        self.strategy_b_pending = False

    def on_data(self, data):
        spy_crossed_above = False
        spy_crossed_below = False

        if data.bars.contains_key(self.spy):
            spy_bar = data.bars[self.spy]
            self.spy_sma.update(spy_bar.end_time, spy_bar.close)

            if self.spy_sma.is_ready:
                current_sma = self.spy_sma.current.value

                if (
                    self.previous_spy_close is not None
                    and self.previous_spy_sma is not None
                ):
                    spy_crossed_above = (
                        self.previous_spy_close <= self.previous_spy_sma
                        and spy_bar.close > current_sma
                    )
                    spy_crossed_below = (
                        self.previous_spy_close >= self.previous_spy_sma
                        and spy_bar.close < current_sma
                    )

                self.previous_spy_close = spy_bar.close
                self.previous_spy_sma = current_sma

        if data.bars.contains_key(self.aapl):
            aapl_bar = data.bars[self.aapl]
            self.aapl_rsi.update(aapl_bar.end_time, aapl_bar.close)
            self.aapl_samples += 1

            if self.previous_aapl_close is not None:
                if aapl_bar.close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

            self.previous_aapl_close = aapl_bar.close

        if not all(
            data.bars.contains_key(symbol)
            for symbol in self.symbols.values()
        ):
            return

        all_state_ready = (
            self.previous_spy_sma is not None
            and self.previous_spy_close is not None
            and self.aapl_rsi.is_ready
            and self.aapl_samples >= 4
        )
        if not all_state_ready:
            return

        spy_close = data.bars[self.spy].close
        aapl_close = data.bars[self.aapl].close

        # Evaluate all sells before any buys.
        if (
            self.strategy_a_lot > 0
            and not self.strategy_a_pending
            and spy_crossed_below
        ):
            self.strategy_a_pending = True
            ticket = self.market_order(
                self.spy,
                -self.strategy_a_lot,
                tag="STRATEGY_A_SELL"
            )
            if ticket is None:
                self.strategy_a_pending = False

        if (
            self.strategy_b_lot > 0
            and not self.strategy_b_pending
            and self.aapl_rsi.current.value > Decimal("60")
        ):
            self.strategy_b_pending = True
            ticket = self.market_order(
                self.aapl,
                -self.strategy_b_lot,
                tag="STRATEGY_B_SELL"
            )
            if ticket is None:
                self.strategy_b_pending = False

        if (
            self.strategy_a_lot == 0
            and not self.strategy_a_pending
            and spy_crossed_above
        ):
            allocation = (
                Decimal("0.40")
                * self.portfolio.total_portfolio_value
            )
            quantity = int(allocation / spy_close)

            if quantity > 0:
                self.strategy_a_pending = True
                ticket = self.market_order(
                    self.spy,
                    quantity,
                    tag="STRATEGY_A_BUY"
                )
                if ticket is None:
                    self.strategy_a_pending = False

        if (
            self.strategy_b_lot == 0
            and not self.strategy_b_pending
            and self.aapl_red_streak >= 3
            and self.portfolio.cash >= Decimal("20000")
        ):
            quantity = int(Decimal("20000") / aapl_close)

            if quantity > 0:
                self.strategy_b_pending = True
                ticket = self.market_order(
                    self.aapl,
                    quantity,
                    tag="STRATEGY_B_BUY"
                )
                if ticket is None:
                    self.strategy_b_pending = False

    def on_order_event(self, order_event):
        order = self.transactions.get_order_by_id(order_event.order_id)
        if order is None:
            return

        tag = order.tag or ""
        fill_quantity = int(order_event.fill_quantity)

        if tag.startswith("STRATEGY_A_"):
            if fill_quantity != 0:
                self.strategy_a_lot += fill_quantity
                if self.strategy_a_lot < 0:
                    self.strategy_a_lot = 0

            if order_event.status in [
                OrderStatus.FILLED,
                OrderStatus.CANCELED,
                OrderStatus.INVALID
            ]:
                self.strategy_a_pending = False

        elif tag.startswith("STRATEGY_B_"):
            if fill_quantity != 0:
                self.strategy_b_lot += fill_quantity
                if self.strategy_b_lot < 0:
                    self.strategy_b_lot = 0

            if order_event.status in [
                OrderStatus.FILLED,
                OrderStatus.CANCELED,
                OrderStatus.INVALID
            ]:
                self.strategy_b_pending = False

from AlgorithmImports import *


class ParallelEquityStrategies(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            security = self.AddEquity(ticker, Resolution.Daily)
            security.SetDataNormalizationMode(DataNormalizationMode.Adjusted)
            self.symbols[ticker] = security.Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.spy_sma = SimpleMovingAverage(20)
        self.aapl_rsi = RelativeStrengthIndex(
            14, MovingAverageType.Wilders
        )

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.pending_orders = {
            self.spy: False,
            self.aapl: False
        }

    def OnData(self, data):
        spy_bar = data.Bars[self.spy] if data.Bars.ContainsKey(self.spy) else None
        aapl_bar = data.Bars[self.aapl] if data.Bars.ContainsKey(self.aapl) else None

        if spy_bar is not None:
            self.spy_sma.Update(spy_bar.EndTime, spy_bar.Close)

        if aapl_bar is not None:
            if self.previous_aapl_close is not None:
                if aapl_bar.Close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_bar.Close)

        all_bars_present = all(
            data.Bars.ContainsKey(symbol)
            for symbol in self.symbols.values()
        )

        if all_bars_present:
            spy_close = spy_bar.Close
            spy_sma_value = (
                self.spy_sma.Current.Value
                if self.spy_sma.IsReady
                else None
            )

            spy_quantity = int(self.Portfolio[self.spy].Quantity)
            aapl_quantity = int(self.Portfolio[self.aapl].Quantity)

            # Evaluate every sell before evaluating any buy.
            if (
                spy_quantity > 0
                and not self.pending_orders[self.spy]
                and self.spy_sma.IsReady
                and self.previous_spy_close is not None
                and self.previous_spy_sma is not None
                and self.previous_spy_close >= self.previous_spy_sma
                and spy_close < spy_sma_value
            ):
                ticket = self.MarketOrder(self.spy, -spy_quantity)
                if ticket is not None:
                    self.pending_orders[self.spy] = True

            if (
                aapl_quantity > 0
                and not self.pending_orders[self.aapl]
                and self.aapl_rsi.IsReady
                and self.aapl_rsi.Current.Value > 60
            ):
                ticket = self.MarketOrder(self.aapl, -aapl_quantity)
                if ticket is not None:
                    self.pending_orders[self.aapl] = True

            if (
                spy_quantity == 0
                and not self.pending_orders[self.spy]
                and self.spy_sma.IsReady
                and self.previous_spy_close is not None
                and self.previous_spy_sma is not None
                and self.previous_spy_close <= self.previous_spy_sma
                and spy_close > spy_sma_value
            ):
                quantity = int(
                    0.40
                    * float(self.Portfolio.TotalPortfolioValue)
                    / float(spy_close)
                )
                if quantity > 0:
                    ticket = self.MarketOrder(self.spy, quantity)
                    if ticket is not None:
                        self.pending_orders[self.spy] = True

            available_cash = float(self.Portfolio.CashBook["USD"].Amount)
            if (
                aapl_quantity == 0
                and not self.pending_orders[self.aapl]
                and self.aapl_rsi.IsReady
                and self.aapl_red_streak >= 3
                and available_cash >= 20_000
            ):
                quantity = int(20_000 // float(aapl_bar.Close))
                if quantity > 0:
                    ticket = self.MarketOrder(self.aapl, quantity)
                    if ticket is not None:
                        self.pending_orders[self.aapl] = True

        if spy_bar is not None:
            self.previous_spy_close = spy_bar.Close
            self.previous_spy_sma = (
                self.spy_sma.Current.Value
                if self.spy_sma.IsReady
                else None
            )

        if aapl_bar is not None:
            self.previous_aapl_close = aapl_bar.Close

    def OnOrderEvent(self, order_event):
        if order_event.Symbol not in self.pending_orders:
            return

        if order_event.Status in [
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ]:
            self.pending_orders[order_event.Symbol] = False

