class StrategySystemAlgorithm(QCAlgorithm):
    MOVING_AVERAGE_PERIOD = 200

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            security = self.AddEquity(
                ticker,
                Resolution.Daily,
                Market.USA,
                False
            )
            self.symbols[ticker] = security.Symbol

        self.spy_sma = SimpleMovingAverage(self.MOVING_AVERAGE_PERIOD)
        self.aapl_rsi = RelativeStrengthIndex(
            14,
            MovingAverageType.Wilders
        )

        self.spy_previous_ready_close = None
        self.spy_previous_ready_ma = None

        self.aapl_previous_close = None
        self.aapl_red_streak = 0

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

        self.strategy_a_buy_pending = False
        self.strategy_a_sell_pending = False
        self.strategy_b_buy_pending = False
        self.strategy_b_sell_pending = False

    def OnData(self, data):
        self.strategy_a_lot = max(
            0, int(self.Portfolio[self.symbols["SPY"]].Quantity)
        )
        self.strategy_b_lot = max(
            0, int(self.Portfolio[self.symbols["AAPL"]].Quantity)
        )

        bars = {}
        for ticker, symbol in self.symbols.items():
            if data.Bars.ContainsKey(symbol):
                bars[ticker] = data.Bars[symbol]

        spy_crossed_above = False
        spy_crossed_below = False

        if "SPY" in bars:
            spy_bar = bars["SPY"]
            self.spy_sma.Update(spy_bar.EndTime, spy_bar.Close)

            if self.spy_sma.IsReady:
                current_close = float(spy_bar.Close)
                current_ma = float(self.spy_sma.Current.Value)

                if (
                    self.spy_previous_ready_close is not None
                    and self.spy_previous_ready_ma is not None
                ):
                    spy_crossed_above = (
                        self.spy_previous_ready_close
                        <= self.spy_previous_ready_ma
                        and current_close > current_ma
                    )
                    spy_crossed_below = (
                        self.spy_previous_ready_close
                        >= self.spy_previous_ready_ma
                        and current_close < current_ma
                    )

                self.spy_previous_ready_close = current_close
                self.spy_previous_ready_ma = current_ma

        if "AAPL" in bars:
            aapl_bar = bars["AAPL"]
            current_aapl_close = float(aapl_bar.Close)

            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_bar.Close)

            if self.aapl_previous_close is not None:
                if current_aapl_close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

            self.aapl_previous_close = current_aapl_close

        if len(bars) != len(self.symbols):
            return

        if (
            not self.spy_sma.IsReady
            or not self.aapl_rsi.IsReady
            or self.spy_previous_ready_close is None
            or self.spy_previous_ready_ma is None
        ):
            return

        spy_close = float(bars["SPY"].Close)
        aapl_close = float(bars["AAPL"].Close)

        # Evaluate all sells before any buys.

        if (
            self.strategy_a_lot > 0
            and not self.strategy_a_sell_pending
            and not self.strategy_a_buy_pending
            and spy_crossed_below
        ):
            self.strategy_a_sell_pending = True
            self.MarketOrder(
                self.symbols["SPY"],
                -self.strategy_a_lot,
                False,
                "STRATEGY_A_SELL"
            )

        if (
            self.strategy_b_lot > 0
            and not self.strategy_b_sell_pending
            and not self.strategy_b_buy_pending
            and float(self.aapl_rsi.Current.Value) > 60.0
        ):
            self.strategy_b_sell_pending = True
            self.MarketOrder(
                self.symbols["AAPL"],
                -self.strategy_b_lot,
                False,
                "STRATEGY_B_SELL"
            )

        if (
            self.strategy_a_lot == 0
            and not self.strategy_a_buy_pending
            and not self.strategy_a_sell_pending
            and spy_crossed_above
        ):
            target_value = 0.40 * float(self.Portfolio.TotalPortfolioValue)
            quantity = floor(target_value / spy_close)

            if quantity > 0:
                self.strategy_a_buy_pending = True
                self.MarketOrder(
                    self.symbols["SPY"],
                    quantity,
                    False,
                    "STRATEGY_A_BUY"
                )

        if (
            self.strategy_b_lot == 0
            and not self.strategy_b_buy_pending
            and not self.strategy_b_sell_pending
            and self.aapl_red_streak >= 3
        ):
            available_cash = float(self.Portfolio.Cash)

            if available_cash >= 20_000.0:
                quantity = floor(20_000.0 / aapl_close)

                if quantity > 0:
                    self.strategy_b_buy_pending = True
                    self.MarketOrder(
                        self.symbols["AAPL"],
                        quantity,
                        False,
                        "STRATEGY_B_BUY"
                    )

    def OnOrderEvent(self, order_event):
        order = self.Transactions.GetOrderById(order_event.OrderId)
        if order is None:
            return

        tag = order.Tag

        if order_event.FillQuantity != 0:
            fill_quantity = int(order_event.FillQuantity)

            if tag == "STRATEGY_A_BUY":
                self.strategy_a_lot += max(0, fill_quantity)
            elif tag == "STRATEGY_A_SELL":
                self.strategy_a_lot = max(
                    0, self.strategy_a_lot + fill_quantity
                )
            elif tag == "STRATEGY_B_BUY":
                self.strategy_b_lot += max(0, fill_quantity)
            elif tag == "STRATEGY_B_SELL":
                self.strategy_b_lot = max(
                    0, self.strategy_b_lot + fill_quantity
                )

        if order_event.Status in [
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ]:
            if tag == "STRATEGY_A_BUY":
                self.strategy_a_buy_pending = False
            elif tag == "STRATEGY_A_SELL":
                self.strategy_a_sell_pending = False
            elif tag == "STRATEGY_B_BUY":
                self.strategy_b_buy_pending = False
            elif tag == "STRATEGY_B_SELL":
                self.strategy_b_sell_pending = False

