class IndependentStrategySystem(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {
            ticker: self.AddEquity(ticker, Resolution.Daily).Symbol
            for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        }

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.spy_ma_period = 20
        self.spy_closes = deque(maxlen=self.spy_ma_period + 1)

        self.aapl_closes = deque(maxlen=2)
        self.aapl_red_streak = 0

        self.rsi_period = 14
        self.rsi_previous_close = None
        self.rsi_seed_gains = deque(maxlen=self.rsi_period)
        self.rsi_seed_losses = deque(maxlen=self.rsi_period)
        self.rsi_average_gain = None
        self.rsi_average_loss = None
        self.aapl_rsi = None

        self.strategy_a_invested = False
        self.strategy_b_invested = False

    def OnData(self, data):
        bars = data.Bars

        if bars.ContainsKey(self.spy):
            self.spy_closes.append(float(bars[self.spy].Close))

        if bars.ContainsKey(self.aapl):
            aapl_close = float(bars[self.aapl].Close)
            self._update_aapl_red_streak(aapl_close)
            self._update_aapl_rsi(aapl_close)
            self.aapl_closes.append(aapl_close)

        if not all(bars.ContainsKey(symbol) for symbol in self.symbols.values()):
            return

        if not self._all_state_ready():
            return

        spy_close = float(bars[self.spy].Close)
        aapl_close = float(bars[self.aapl].Close)

        previous_spy_close = self.spy_closes[-2]
        previous_spy_ma = (
            sum(list(self.spy_closes)[:-1]) / self.spy_ma_period
        )
        current_spy_ma = (
            sum(list(self.spy_closes)[-self.spy_ma_period:])
            / self.spy_ma_period
        )

        spy_crosses_above = (
            previous_spy_close <= previous_spy_ma
            and spy_close > current_spy_ma
        )
        spy_crosses_below = (
            previous_spy_close >= previous_spy_ma
            and spy_close < current_spy_ma
        )

        # Strategy A: sells before buys.
        if self.strategy_a_invested:
            if spy_crosses_below:
                self.Liquidate(self.spy, "Strategy A: close crossed below MA")
                self.strategy_a_invested = False
        elif spy_crosses_above:
            quantity = self.CalculateOrderQuantity(self.spy, 0.40)
            if quantity > 0:
                self.MarketOrder(
                    self.spy,
                    quantity,
                    tag="Strategy A: close crossed above MA",
                )
                self.strategy_a_invested = True

        # Strategy B: sells before buys.
        if self.strategy_b_invested:
            if self.aapl_rsi > 60:
                self.Liquidate(self.aapl, "Strategy B: RSI above 60")
                self.strategy_b_invested = False
        elif self.aapl_red_streak >= 3:
            cash_to_invest = 20_000
            available_cash = float(self.Portfolio.Cash)
            if available_cash >= cash_to_invest:
                quantity = int(cash_to_invest // aapl_close)
                if quantity > 0:
                    self.MarketOrder(
                        self.aapl,
                        quantity,
                        tag="Strategy B: three consecutive red days",
                    )
                    self.strategy_b_invested = True

    def _update_aapl_red_streak(self, close):
        if len(self.aapl_closes) == 0:
            self.aapl_red_streak = 0
        elif close < self.aapl_closes[-1]:
            self.aapl_red_streak += 1
        else:
            self.aapl_red_streak = 0

    def _update_aapl_rsi(self, close):
        if self.rsi_previous_close is None:
            self.rsi_previous_close = close
            return

        change = close - self.rsi_previous_close
        gain = max(change, 0.0)
        loss = max(-change, 0.0)

        if self.rsi_average_gain is None:
            self.rsi_seed_gains.append(gain)
            self.rsi_seed_losses.append(loss)

            if len(self.rsi_seed_gains) == self.rsi_period:
                self.rsi_average_gain = (
                    sum(self.rsi_seed_gains) / self.rsi_period
                )
                self.rsi_average_loss = (
                    sum(self.rsi_seed_losses) / self.rsi_period
                )
                self.aapl_rsi = self._calculate_rsi()
        else:
            self.rsi_average_gain = (
                self.rsi_average_gain * (self.rsi_period - 1) + gain
            ) / self.rsi_period
            self.rsi_average_loss = (
                self.rsi_average_loss * (self.rsi_period - 1) + loss
            ) / self.rsi_period
            self.aapl_rsi = self._calculate_rsi()

        self.rsi_previous_close = close

    def _calculate_rsi(self):
        if self.rsi_average_loss == 0:
            if self.rsi_average_gain == 0:
                return 50.0
            return 100.0

        relative_strength = (
            self.rsi_average_gain / self.rsi_average_loss
        )
        return 100.0 - (100.0 / (1.0 + relative_strength))

    def _all_state_ready(self):
        return (
            len(self.spy_closes) == self.spy_ma_period + 1
            and len(self.aapl_closes) == 2
            and self.aapl_rsi is not None
        )

