class ParallelStrategySystem(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.AddEquity(
                ticker, Resolution.Daily
            ).Symbol

        self.spy_ma_period = 20
        self.spy_closes = deque(maxlen=self.spy_ma_period)
        self.previous_spy_close = None
        self.previous_spy_ma = None
        self.current_spy_ma = None

        self.previous_aapl_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(
            14, MovingAverageType.Wilders
        )

    def OnData(self, data):
        bars = {}

        for ticker, symbol in self.symbols.items():
            if data.Bars.ContainsKey(symbol):
                bars[ticker] = data.Bars[symbol]

        spy_bar = bars.get("SPY")
        if spy_bar is not None:
            spy_close = float(spy_bar.Close)
            self.spy_closes.append(spy_close)

            if len(self.spy_closes) == self.spy_ma_period:
                self.current_spy_ma = (
                    sum(self.spy_closes) / self.spy_ma_period
                )
            else:
                self.current_spy_ma = None

        aapl_bar = bars.get("AAPL")
        if aapl_bar is not None:
            aapl_close = float(aapl_bar.Close)

            if self.previous_aapl_close is not None:
                if aapl_close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_bar.Close)

        all_bars_present = len(bars) == len(self.symbols)

        indicators_ready = (
            self.current_spy_ma is not None
            and self.previous_spy_ma is not None
            and self.previous_spy_close is not None
            and self.aapl_rsi.IsReady
            and self.previous_aapl_close is not None
        )

        if all_bars_present and indicators_ready:
            spy = self.symbols["SPY"]
            aapl = self.symbols["AAPL"]

            spy_close = float(spy_bar.Close)
            aapl_close = float(aapl_bar.Close)

            spy_quantity = int(self.Portfolio[spy].Quantity)
            aapl_quantity = int(self.Portfolio[aapl].Quantity)

            spy_has_open_orders = (
                len(self.Transactions.GetOpenOrders(spy)) > 0
            )
            aapl_has_open_orders = (
                len(self.Transactions.GetOpenOrders(aapl)) > 0
            )

            spy_crossed_below = (
                self.previous_spy_close >= self.previous_spy_ma
                and spy_close < self.current_spy_ma
            )

            if (
                spy_quantity > 0
                and not spy_has_open_orders
                and spy_crossed_below
            ):
                self.MarketOrder(
                    spy,
                    -spy_quantity,
                    tag="Strategy A: close crossed below moving average",
                )

            if (
                aapl_quantity > 0
                and not aapl_has_open_orders
                and float(self.aapl_rsi.Current.Value) > 60.0
            ):
                self.MarketOrder(
                    aapl,
                    -aapl_quantity,
                    tag="Strategy B: RSI closed above 60",
                )

            spy_quantity = int(self.Portfolio[spy].Quantity)
            aapl_quantity = int(self.Portfolio[aapl].Quantity)

            spy_has_open_orders = (
                len(self.Transactions.GetOpenOrders(spy)) > 0
            )
            aapl_has_open_orders = (
                len(self.Transactions.GetOpenOrders(aapl)) > 0
            )

            spy_crossed_above = (
                self.previous_spy_close <= self.previous_spy_ma
                and spy_close > self.current_spy_ma
            )

            if (
                spy_quantity == 0
                and not spy_has_open_orders
                and spy_crossed_above
            ):
                target_value = (
                    float(self.Portfolio.TotalPortfolioValue) * 0.40
                )
                quantity = floor(target_value / spy_close)

                if quantity > 0:
                    self.MarketOrder(
                        spy,
                        quantity,
                        tag="Strategy A: close crossed above moving average",
                    )

            available_cash = float(
                self.Portfolio.CashBook["USD"].Amount
            )

            if (
                aapl_quantity == 0
                and not aapl_has_open_orders
                and self.aapl_red_streak >= 3
                and available_cash >= 20_000.0
            ):
                quantity = floor(20_000.0 / aapl_close)

                if quantity > 0:
                    self.MarketOrder(
                        aapl,
                        quantity,
                        tag="Strategy B: red for at least 3 consecutive days",
                    )

        if spy_bar is not None:
            self.previous_spy_close = float(spy_bar.Close)
            if self.current_spy_ma is not None:
                self.previous_spy_ma = self.current_spy_ma

        if aapl_bar is not None:
            self.previous_aapl_close = float(aapl_bar.Close)

