        aapl_bar = data.Bars[aapl] if aapl in data.Bars else None

        spy_crosses_above = False
        spy_crosses_below = False

        if spy_bar is not None:
            self.spy_closes.append(spy_bar.Close)

            current_spy_sma = None
            if len(self.spy_closes) == 100:
                current_spy_sma = sum(self.spy_closes) / 100

                if (
                    self.previous_spy_close is not None
                    and self.previous_spy_sma is not None
                ):
                    spy_crosses_above = (
                        self.previous_spy_close <= self.previous_spy_sma
                        and spy_bar.Close > current_spy_sma
                    )
                    spy_crosses_below = (
                        self.previous_spy_close >= self.previous_spy_sma
                        and spy_bar.Close < current_spy_sma
                    )

                self.previous_spy_sma = current_spy_sma

            self.previous_spy_close = spy_bar.Close

        if aapl_bar is not None:
            if self.previous_aapl_close is not None:
                if aapl_bar.Close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

            self.previous_aapl_close = aapl_bar.Close
            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_bar.Close)

        if any(self.symbols[ticker] not in data.Bars for ticker in self.symbols):
            return

        all_state_ready = (
            len(self.spy_closes) == 100
            and self.previous_spy_sma is not None
            and self.aapl_rsi.IsReady
            and self.previous_aapl_close is not None
        )
        if not all_state_ready:
            return

        # Evaluate sells before buys.
        if (
            self.lots["A"] > 0
            and self.pending_orders["A"] is None
            and spy_crosses_below
        ):
            self._submit_order("A", spy, -self.lots["A"], "Strategy A sell")

        if (
            self.lots["B"] > 0
            and self.pending_orders["B"] is None
            and self.aapl_rsi.Current.Value > 60
        ):
            self._submit_order("B", aapl, -self.lots["B"], "Strategy B sell")

        if (
            self.lots["A"] == 0
            and self.pending_orders["A"] is None
            and spy_crosses_above
        ):
            quantity = int(self.CalculateOrderQuantity(spy, 0.40))
            if quantity > 0:
                self._submit_order(
                    "A", spy, quantity, "Strategy A buy"
                )

        if (
            self.lots["B"] == 0
            and self.pending_orders["B"] is None
            and self.aapl_red_streak >= 3
        ):
            available_cash = self.Portfolio.CashBook[
                self.AccountCurrency
            ].Amount

            if available_cash >= 20_000:
                quantity = math.floor(20_000 / float(aapl_bar.Close))
                if quantity > 0:
                    self._submit_order(
                        "B", aapl, quantity, "Strategy B buy"
                    )

    def _submit_order(self, owner, symbol, quantity, tag):
        ticket = self.MarketOrder(symbol, quantity, False, tag)
        self.pending_orders[owner] = ticket.OrderId
        self.order_owners[ticket.OrderId] = owner

        if ticket.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ):
            if ticket.Status != OrderStatus.Filled:
                self.pending_orders[owner] = None
                self.order_owners.pop(ticket.OrderId, None)

    def OnOrderEvent(self, order_event):
        owner = self.order_owners.get(order_event.OrderId)
        if owner is None:
            return

        if order_event.FillQuantity != 0:
            self.lots[owner] += int(order_event.FillQuantity)
            if self.lots[owner] < 0:
                self.lots[owner] = 0

        if order_event.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ):
            self.pending_orders[owner] = None
            self.order_owners.pop(order_event.OrderId, None)

    def _apply_splits(self, data):
        owners_by_symbol = {
            self.symbols["SPY"]: "A",
            self.symbols["AAPL"]: "B"
        }

        for symbol, owner in owners_by_symbol.items():
            if symbol not in data.Splits:
                continue

            split = data.Splits[symbol]
            if (
                split.Type == SplitType.SplitOccurred
                and split.SplitFactor > 0
                and self.lots[owner] > 0
            ):
                self.lots[owner] = int(
                    self.lots[owner] / split.SplitFactor
                )
