from AlgorithmImports import *
from collections import deque
import math


class ExactStrategySystem(QCAlgorithm):

    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.spy = self.add_equity("SPY", Resolution.DAILY).symbol
        self.aapl = self.add_equity("AAPL", Resolution.DAILY).symbol
        self.ibm = self.add_equity("IBM", Resolution.DAILY).symbol
        self.bac = self.add_equity("BAC", Resolution.DAILY).symbol
        self.aig = self.add_equity("AIG", Resolution.DAILY).symbol

        self.subscribed_symbols = [
            self.spy,
            self.aapl,
            self.ibm,
            self.bac,
            self.aig
        ]

        self.spy_closes = deque()
        self.spy_close_sum = 0.0
        self.spy_previous_close = None
        self.spy_previous_sma = None

        self.aapl_previous_close = None
        self.aapl_red_streak = 0

        self.rsi_period = 14
        self.rsi_change_count = 0
        self.rsi_gain_sum = 0.0
        self.rsi_loss_sum = 0.0
        self.rsi_average_gain = None
        self.rsi_average_loss = None
        self.aapl_rsi = None

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

    def on_data(self, data):
        bars = {}
        for symbol in self.subscribed_symbols:
            if symbol in data.bars:
                bars[symbol] = data.bars[symbol]

        spy_crossed_above = False
        spy_crossed_below = False

        if self.spy in bars:
            spy_close = float(bars[self.spy].close)

            if len(self.spy_closes) == 100:
                self.spy_close_sum -= self.spy_closes.popleft()

            self.spy_closes.append(spy_close)
            self.spy_close_sum += spy_close

            current_spy_sma = None
            if len(self.spy_closes) == 100:
                current_spy_sma = self.spy_close_sum / 100.0

                if (
                    self.spy_previous_close is not None
                    and self.spy_previous_sma is not None
                ):
                    spy_crossed_above = (
                        self.spy_previous_close <= self.spy_previous_sma
                        and spy_close > current_spy_sma
                    )
                    spy_crossed_below = (
                        self.spy_previous_close >= self.spy_previous_sma
                        and spy_close < current_spy_sma
                    )

                self.spy_previous_sma = current_spy_sma

            self.spy_previous_close = spy_close

        if self.aapl in bars:
            aapl_close = float(bars[self.aapl].close)

            if self.aapl_previous_close is not None:
                if aapl_close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

                change = aapl_close - self.aapl_previous_close
                gain = max(change, 0.0)
                loss = max(-change, 0.0)

                if self.rsi_change_count < self.rsi_period:
                    self.rsi_gain_sum += gain
                    self.rsi_loss_sum += loss
                    self.rsi_change_count += 1

                    if self.rsi_change_count == self.rsi_period:
                        self.rsi_average_gain = (
                            self.rsi_gain_sum / self.rsi_period
                        )
                        self.rsi_average_loss = (
                            self.rsi_loss_sum / self.rsi_period
                        )
                else:
                    self.rsi_average_gain = (
                        (self.rsi_average_gain * (self.rsi_period - 1)) + gain
                    ) / self.rsi_period
                    self.rsi_average_loss = (
                        (self.rsi_average_loss * (self.rsi_period - 1)) + loss
                    ) / self.rsi_period

                if self.rsi_average_gain is not None:
                    if (
                        self.rsi_average_gain == 0.0
                        and self.rsi_average_loss == 0.0
                    ):
                        self.aapl_rsi = 50.0
                    elif self.rsi_average_loss == 0.0:
                        self.aapl_rsi = 100.0
                    else:
                        relative_strength = (
                            self.rsi_average_gain / self.rsi_average_loss
                        )
                        self.aapl_rsi = (
                            100.0 - (100.0 / (1.0 + relative_strength))
                        )

            self.aapl_previous_close = aapl_close

        if len(bars) != len(self.subscribed_symbols):
            return

        if len(self.spy_closes) < 100 or self.aapl_rsi is None:
            return

        if self.strategy_a_lot > 0 and spy_crossed_below:
            self.market_order(self.spy, -self.strategy_a_lot)
            self.strategy_a_lot = 0

        if self.strategy_b_lot > 0 and self.aapl_rsi > 60.0:
            self.market_order(self.aapl, -self.strategy_b_lot)
            self.strategy_b_lot = 0

        if self.strategy_a_lot == 0 and spy_crossed_above:
            quantity = self.calculate_order_quantity(self.spy, 0.40)
            if quantity > 0:
                self.market_order(self.spy, quantity)
                self.strategy_a_lot = quantity

        if self.strategy_b_lot == 0 and self.aapl_red_streak >= 3:
            if self.portfolio.cash >= 20_000:
                aapl_close = float(bars[self.aapl].close)
                quantity = math.floor(20_000 / aapl_close)
                if quantity > 0:
                    self.market_order(self.aapl, quantity)
                    self.strategy_b_lot = quantity

