from AlgorithmImports import *
import math


class ExactStrategySystemAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            security = self.AddEquity(
                ticker,
                Resolution.Daily,
                Market.USA,
                False
            )
            self.symbols[ticker] = security.Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.spy_closes = []
        self.aapl_previous_close = None
        self.aapl_close_count = 0
        self.aapl_red_streak = 0

        self.aapl_rsi = RelativeStrengthIndex(
            14,
            MovingAverageType.Wilders
        )

        self.spy_lot = 0
        self.aapl_lot = 0

        self.SetWarmUp(101, Resolution.Daily)

    def OnData(self, data):
        if data.Bars.ContainsKey(self.spy):
            spy_bar = data.Bars[self.spy]
            self.spy_closes.append(float(spy_bar.Close))
            if len(self.spy_closes) > 101:
                self.spy_closes.pop(0)

        if data.Bars.ContainsKey(self.aapl):
            aapl_bar = data.Bars[self.aapl]
            aapl_close = float(aapl_bar.Close)

            if self.aapl_previous_close is None:
                self.aapl_red_streak = 0
            elif aapl_close < self.aapl_previous_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

            self.aapl_previous_close = aapl_close
            self.aapl_close_count += 1
            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_bar.Close)

        if self.IsWarmingUp:
            return

        for symbol in self.symbols.values():
            if not data.Bars.ContainsKey(symbol):
                return

        if (
            len(self.spy_closes) < 101
            or self.aapl_close_count < 4
            or not self.aapl_rsi.IsReady
        ):
            return

        spy_close_today = self.spy_closes[-1]
        spy_close_yesterday = self.spy_closes[-2]
        spy_sma_today = sum(self.spy_closes[-100:]) / 100.0
        spy_sma_yesterday = sum(self.spy_closes[-101:-1]) / 100.0

        spy_crossed_above = (
            spy_close_yesterday <= spy_sma_yesterday
            and spy_close_today > spy_sma_today
        )
        spy_crossed_below = (
            spy_close_yesterday >= spy_sma_yesterday
            and spy_close_today < spy_sma_today
        )

        if self.spy_lot > 0 and spy_crossed_below:
            ticket = self.MarketOrder(self.spy, -self.spy_lot)
            filled = abs(int(ticket.QuantityFilled))
            self.spy_lot = max(0, self.spy_lot - filled)

        if self.aapl_lot > 0 and float(self.aapl_rsi.Current.Value) > 60:
            ticket = self.MarketOrder(self.aapl, -self.aapl_lot)
            filled = abs(int(ticket.QuantityFilled))
            self.aapl_lot = max(0, self.aapl_lot - filled)

        if self.spy_lot == 0 and spy_crossed_above:
            quantity = int(self.CalculateOrderQuantity(self.spy, 0.40))
            if quantity > 0:
                ticket = self.MarketOrder(self.spy, quantity)
                filled = int(ticket.QuantityFilled)
                if filled > 0:
                    self.spy_lot = filled

        if self.aapl_lot == 0 and self.aapl_red_streak >= 3:
            if float(self.Portfolio.Cash) >= 20_000:
                aapl_close = float(data.Bars[self.aapl].Close)
                quantity = math.floor(20_000 / aapl_close)
                if quantity > 0:
                    ticket = self.MarketOrder(self.aapl, quantity)
                    filled = int(ticket.QuantityFilled)
                    if filled > 0:
                        self.aapl_lot = filled

